import json, html
from pathlib import Path
from PIL import Image

root=Path(__file__).resolve().parent
d=json.loads((root/'manifest.json').read_text())
for p in d['pages']:
    f=root/p['file']
    p['status']='complete' if f.exists() else 'pending'
    if f.exists():
        with Image.open(f) as image:
            image.verify()
        with Image.open(f) as image:
            p['dimensions']=list(image.size)
(root/'manifest.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
payload=json.dumps(d,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AgentCom · 全页面效果图</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#102a43;font-family:system-ui,"Microsoft YaHei",sans-serif}header{background:#102a43;color:white;padding:26px 4vw}header h1{margin:0 0 9px;font-size:25px}header p{margin:0;color:#c0d1e3;font-size:14px;line-height:1.8}main{padding:24px 4vw}nav{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}button,input{font:inherit;border:1px solid #dbe3ec;border-radius:7px;background:white;padding:10px 14px;cursor:pointer;color:#334e68}button.active{background:#246bfd;color:#fff;border-color:#246bfd}input{min-width:290px;cursor:text;margin:0 12px 18px 0}.summary{font-size:14px;color:#64748b}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(370px,1fr));gap:20px}.card{background:white;border:1px solid #e1e8f0;border-radius:10px;overflow:hidden}.card img{width:100%;display:block;aspect-ratio:16/9;object-fit:contain;background:#eaf0f6;cursor:zoom-in}.info{padding:15px}.info h2{font-size:17px;margin:0 0 7px}.info p{margin:0;color:#64748b;font-size:12px}.info a{color:#246bfd;font-size:13px;display:inline-block;margin-top:10px}.pending{display:flex;align-items:center;justify-content:center;aspect-ratio:16/9;color:#64748b;background:#eef2f7}details{background:white;border:1px solid #e1e8f0;border-radius:8px;margin:0 0 20px;padding:14px}summary{cursor:pointer}.notes{font-size:14px;line-height:1.9;color:#486581}.notes ul{padding-left:22px}dialog{padding:0;background:#102a43;border:0;border-radius:8px;color:white;width:96vw;max-width:none;max-height:96vh}dialog::backdrop{background:#061625df}.toolbar{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;gap:14px}.toolbar button{padding:7px 12px}.preview{overflow:auto;max-height:82vh;background:#eaf0f6}.preview img{display:block;width:100%;height:auto}.preview img.zoom{width:auto;max-width:none}.subtitle{font-size:13px;color:#c0d1e3}a{color:#5ea1ff}footer{font-size:12px;color:#64748b;padding:30px 0}@media(max-width:600px){.grid{grid-template-columns:1fr}.toolbar{flex-wrap:wrap}input{width:100%;min-width:0}}</style>
<header><h1>AgentCom · 全页面效果图</h1><p>企业与政务协同办公与智慧管理平台 · 需求逐页覆盖 · 图片生成工具制作<br>统一四字导航 / 深蓝全局栏 / 白色功能侧栏 / 浅灰业务画布</p></header>
<main><nav id="nav"></nav><input id="search" aria-label="搜索页面" placeholder="搜索页面、功能或路由"><span id="summary" class="summary"></span>
<details><summary>设计依据与统一规范</summary><div class="notes"><p>依据项目需求说明书第3章的顶部大类＋左侧功能导航，以及第4章全部明确功能路由。共82页：72个明确功能页面、5个综合门户页面、4个知识页面和1个登录页。登录页为业务补充，知识页是GBrainKG嵌入内容的视觉示意，不代表重建独立知识产品。</p><p>顶部导航均为四字、同宽展示：综合门户、考勤管理、资产耗材、重点督办、会务管理、组织通讯、门禁访客、公务用车、调研管理、智慧知识、系统管理。页面完整业务名称保留于侧栏与标题。</p><ul><li>色彩：导航 #102A43；背景 #F3F6FA；主操作 #246BFD；辅助完成态 #13A89E；临期 #F59E0B；超期 #E5484D。</li><li>尺寸基线：全局栏56px、功能侧栏208px、内容间距24px、卡片圆角8px；实际效果图为生成式视觉参考，开发按基线实施。</li><li>督办正常状态按说明书中的“红黄蓝”规格统一为蓝；文字标签同时表达状态，解决正文部分使用绿色的矛盾。</li><li>用车需求标题写“三级审批”，正文只明确部门与后勤两级；效果图补充“分管领导/授权审批”为可配置第三级，实施前需明确。菜单权限按M目录、C菜单、F按钮表达。</li><li>审批、派发、执行、核验、归档的流程按各模块分别展现；会务决议和调研问题保留来源关联后转督办。</li><li>通讯录与身份信息脱敏、页面追溯水印、凭据密钥遮挡；样例数据为虚构。智能助手写入前展示可核对的计划。</li><li>本目录是效果图预览，图片中的按钮不能操作业务。生成图的细小文字和日期以需求及manifest.json为准。</li></ul><p><a href="manifest.json">页面需求映射及全部生成提示词（JSON）</a></p></div></details>
<section id="grid" class="grid"></section><footer>生成方式：内置 image_gen · 原始图片保存在 mockups/ · 点击效果图可放大，方向键可切换，Esc关闭。</footer></main>
<dialog id="viewer"><div class="toolbar"><div><strong id="vtitle"></strong><div id="vroute" class="subtitle"></div></div><div><button id="prev">上一页</button> <button id="next">下一页</button> <button id="zoom">原始尺寸</button> <a id="original" target="_blank">打开原图</a> <button id="close">关闭</button></div></div><div class="preview"><img id="vimg" alt="页面效果图"></div></dialog>
<script>const data=PAYLOAD;let selected='全部页面',filtered=[],index=0;const $=id=>document.getElementById(id);const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const q=$('search').value.toLowerCase();filtered=data.pages.filter(p=>(selected==='全部页面'||p.category===selected)&&(p.title+p.route+p.description).toLowerCase().includes(q));$('nav').innerHTML=['全部页面',...data.navigation,'身份入口'].map(c=>`<button class="${selected===c?'active':''}" data-category="${c}">${c}</button>`).join('');$('summary').textContent=`显示 ${filtered.length} 页 / 已生成 ${data.pages.filter(p=>p.status==='complete').length} / 总计 ${data.pages.length}`;$('grid').innerHTML=filtered.map((p,i)=>`<article class="card">${p.status==='complete'?`<img src="${p.file}" loading="lazy" alt="${esc(p.title)}效果图" data-index="${i}">`:'<div class="pending">尚未生成</div>'}<div class="info"><h2>${p.id} · ${esc(p.title)}</h2><p>${p.category} · ${p.route}</p>${p.status==='complete'?`<a href="${p.file}" target="_blank">打开原图${p.dimensions?' · '+p.dimensions.join(' × '):''}</a>`:''}</div></article>`).join('');}function show(i){index=(i+filtered.length)%filtered.length;const p=filtered[index];if(p.status!=='complete')return;$('vtitle').textContent=p.id+' · '+p.title;$('vroute').textContent=p.category+' / '+p.route;$('vimg').src=p.file;$('vimg').classList.remove('zoom');$('original').href=p.file;if(!$('viewer').open)$('viewer').showModal();}$('nav').onclick=e=>{if(e.target.dataset.category){selected=e.target.dataset.category;render();}};$('search').oninput=render;$('grid').onclick=e=>{if(e.target.dataset.index!==undefined)show(Number(e.target.dataset.index));};$('close').onclick=()=>$('viewer').close();$('prev').onclick=()=>show(index-1);$('next').onclick=()=>show(index+1);$('zoom').onclick=()=>$('vimg').classList.toggle('zoom');document.onkeydown=e=>{if(!$('viewer').open)return;if(e.key==='ArrowLeft')show(index-1);if(e.key==='ArrowRight')show(index+1);};render();</script></html>'''
(root/'index.html').write_text(page.replace('PAYLOAD',payload))
complete=sum(p['status']=='complete' for p in d['pages'])
print(f'Gallery refreshed: {complete}/{len(d["pages"])} valid images')
